import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int x = sc.nextInt();
        int[] c = new int[n];
        for (int i = 0; i < n; i++) {
            c[i] = sc.nextInt();
        }

        int maxDestroyed = 0;

        // Try inserting at each of the n+1 possible positions
        for (int pos = 0; pos <= n; pos++) {
            // Build the new sequence after insertion
            List<Integer> row = new ArrayList<>(n + 1);
            for (int i = 0; i < pos; i++) row.add(c[i]);
            row.add(x);
            for (int i = pos; i < n; i++) row.add(c[i]);

            // Simulate the destruction process
            int destroyed = simulateDestruction(row);
            // destroyed counts total balls removed, including the inserted one
            // We want the number of original balls destroyed
            // The inserted ball is not part of the original row
            int originalDestroyed = destroyed;
            // If the inserted ball was destroyed, it's counted in 'destroyed'.
            // We need to subtract 1 if it was destroyed, otherwise 0.
            // Actually, easier: destroyed includes the inserted ball if it vanished.
            // The problem asks for max number of balls *from the row* destroyed.
            // Total balls in row after insertion = n + 1.
            // Balls remaining = (n + 1) - destroyed.
            // Original balls remaining = Balls remaining (since inserted ball is either gone or remains).
            // If inserted ball remains, original remaining = remaining - 1.
            // Original destroyed = n - original remaining.
            // Case 1: Inserted ball destroyed. Remaining = n + 1 - destroyed. All remaining are original.
            // Original destroyed = n - (n + 1 - destroyed) = destroyed - 1.
            // Case 2: Inserted ball not destroyed. Remaining = n + 1 - destroyed. One is inserted.
            // Original remaining = n - destroyed. Original destroyed = destroyed.
            // How to know if inserted ball was destroyed?
            // We can track the index of the inserted ball during simulation, or just check if the final list contains the inserted ball at the tracked position?
            // Since colors can repeat, tracking identity is needed.
            // Alternative: simulate with objects or pairs (color, isInserted).

            // Let's re-simulate with a wrapper class or just track the index.
            // Actually, simpler: The total destroyed count includes the inserted ball iff it disappeared.
            // We can just compute original_destroyed = destroyed - (inserted_was_destroyed ? 1 : 0).
            // To know if inserted was destroyed, we can check if the final row size is n+1 - destroyed.
            // If inserted ball remains, it must be in the final row.
            // Since we only have colors in the final row, we can't distinguish.
            // Better: Simulate with a List of objects (color, boolean isInserted).
        }

        // Re-implementing with object tracking
        class Ball {
            int color;
            boolean isInserted;
            Ball(int color, boolean isInserted) { this.color = color; this.isInserted = isInserted; }
        }

        maxDestroyed = 0;
        for (int pos = 0; pos <= n; pos++) {
            List<Ball> row = new ArrayList<>(n + 1);
            for (int i = 0; i < pos; i++) row.add(new Ball(c[i], false));
            row.add(new Ball(x, true));
            for (int i = pos; i < n; i++) row.add(new Ball(c[i], false));

            int destroyedCount = 0;
            boolean changed = true;
            while (changed) {
                changed = false;
                int i = 0;
                while (i < row.size()) {
                    int j = i;
                    while (j < row.size() && row.get(j).color == row.get(i).color) {
                        j++;
                    }
                    int len = j - i;
                    if (len >= 3) {
                        // Destroy balls from i to j-1
                        for (int idx = i; idx < j; idx++) {
                            if (!row.get(idx).isInserted) destroyedCount++;
                        }
                        // Remove them
                        row.subList(i, j).clear();
                        changed = true;
                        // After removal, we need to re-check from before i, because merging might happen.
                        // Actually, standard Zuma logic: after removing [i, j), the neighbors are i-1 and i (new).
                        // We can just restart scan from max(0, i-1) or just restart from 0.
                        // Since n <= 100, restarting from 0 is fine.
                        break; // break inner while to restart outer while
                    } else {
                        i = j;
                    }
                }
            }
            maxDestroyed = Math.max(maxDestroyed, destroyedCount);
        }

        System.out.println(maxDestroyed);
    }

    // Old simulate method without tracking inserted ball - removed
    // private static int simulateDestruction(List<Integer> row) { ... }
}
